const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install();await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;j.select(0);profileStorage.setItem(j.key,JSON.stringify({version:1,lessons:{0:{passed:true,best:100}},final:{passed:true,best:100}}));sessionStorage.setItem('residentsFirst',profileStorage.getItem(j.key));j.select(1);if(document.querySelector('.lighthouse-beacon'))throw Error('First-island reward lit the second island');if(document.querySelectorAll('[data-resident-visit]').length!==6)throw Error('Missing six residents');});
fs.mkdirSync('audit-screenshots',{recursive:true});const people=await p.evaluate(()=>DEUTSCH_RESIDENTS.map(r=>({id:r.id,index:r.index})));
for(const r of people){for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});await p.evaluate(i=>DEUTSCH_JOURNEY.open(i),r.index);await p.locator('#learningView img').evaluateAll(xs=>xs.forEach(i=>i.loading='eager'));await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.clock.runFor(100);const state=await p.locator('[data-resident-state]').getAttribute('data-resident');if(state!==r.id||await p.locator('.al-study-grid img').count()!==6)throw Error('Wrong resident or changed six-card lesson');if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Resident intro overflow '+r.id+' '+width);if(width===390)await p.screenshot({path:'audit-screenshots/resident-'+r.id+'.png',fullPage:true});}
await p.click('#alContinue');await p.evaluate(id=>{const a=DEUTSCH_ADAPTIVE,s=a.snapshot();if(s.queue.length!==18||s.queue.filter(q=>q.assessment).length!==6)throw Error('Resident changed lesson/test queue');const context=document.querySelector('[data-resident-context]');if(context?.dataset.residentContext!==id||s.batch.some(c=>context.textContent.includes(c.de)))throw Error('Missing context or answer leaked');while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(document.querySelector('[data-resident-state]').dataset.residentState!=='success')throw Error('Missing resident success');},r.id);await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.clock.runFor(100);
await p.evaluate(i=>{const j=DEUTSCH_JOURNEY,a=DEUTSCH_ADAPTIVE;j.open(i);document.querySelector('#alContinue').click();while(!a.snapshot().finished)a.skip();if(document.querySelector('[data-resident-state]').dataset.residentState!=='encourage'||!j.load().lessons[i].passed||j.load().lessons[i].best!==100||j.load().lessons[i].last!==0)throw Error('Missing encouragement or erased seal');},r.index);await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.clock.runFor(100);}
await p.evaluate(()=>{const j=DEUTSCH_JOURNEY,a=DEUTSCH_ADAPTIVE;j.open(0,true);if(document.querySelector('[data-resident-final]')?.dataset.resident!=='karl')throw Error('Keeper missing from final');document.querySelector('#alContinue').click();if(!document.querySelector('[data-resident-context="karl"]'))throw Error('Missing final context');while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(!document.querySelector('[data-resident-final]')?.textContent.includes('Маяк засвітився'))throw Error('Missing lighthouse finale');j.map();if(!document.querySelector('.is-lighthouse-lit .lighthouse-beacon')||!document.querySelector('[data-lighthouse-status="lit"]'))throw Error('Map did not light after final');});
for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.clock.runFor(100);if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Resident roster/lighthouse overflow '+width);if(width!==320)await p.screenshot({path:'audit-screenshots/residents-lit-map-'+width+'.png',fullPage:true});}
await p.emulateMedia({reducedMotion:'reduce'});if(!await p.evaluate(()=>getComputedStyle(document.querySelector('.lighthouse-beacon'),'::before').animationName==='none'))throw Error('Lighthouse ignores reduced motion');await p.evaluate(()=>{const j=DEUTSCH_JOURNEY,a=DEUTSCH_ADAPTIVE;j.open(0,true);document.querySelector('#alContinue').click();while(!a.snapshot().finished)a.skip();if(!j.rewards().lighthouseKey||j.load().final.best!==100||j.load().final.last!==0)throw Error('Failed final erased key/light');j.map();if(!document.querySelector('.lighthouse-beacon'))throw Error('Failed final turned off lighthouse');if(profileStorage.getItem('deutsch16_journey_v1')!==sessionStorage.getItem('residentsFirst'))throw Error('Residents changed first island');});
await p.reload();await p.click('#learningTab');if(await p.locator('.lighthouse-beacon').count()!==1)throw Error('Light did not survive reload');await p.evaluate(()=>{document.documentElement.lang='en';for(const r of DEUTSCH_RESIDENTS){DEUTSCH_JOURNEY.open(r.index);if(!document.querySelector('[data-resident-state]').textContent.includes(r.title[1]))throw Error('Missing English resident '+r.id)}DEUTSCH_JOURNEY.select(0);if(document.querySelector('[data-resident-visit],.lighthouse-beacon'))throw Error('Residents leaked into first island');});
await p.click('#profileButton');await p.fill('#profileAddInput','Resident child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');await p.evaluate(()=>{DEUTSCH_JOURNEY.select(1);if(document.querySelector('.lighthouse-beacon,.resident-card.is-met'))throw Error('Resident or lighthouse progress leaked across profiles');});if(errors.length)throw Error(errors.join(';'));console.log('PASS five distinct residents, 15 loaded poses, unchanged six-card/18-task lessons, contextual practice, success/encouragement, persistent seals and lighthouse, 320–1280px, reduced motion, reload, English and profile isolation');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
